"go.mongodb.org/mongo-driver/v2/mongo/options"
)

func main() {
ctx := context.Background()

// Retrieves your Atlas connection string
const uri = "<connection-string>"

// Connect to your Atlas cluster
clientOptions := options.Client().ApplyURI(uri)
client, err := mongo.Connect(clientOptions)
if err != nil {
log.Fatalf("Failed to connect to the server: %v", err)
}
defer func() {
if err := client.Disconnect(ctx); err != nil {
log.Fatalf("Failed to disconnect: %v", err)
}
}()

// Set the namespace
coll := client.Database("sample_mflix").Collection("movies")
opts := options.SearchIndexes().SetName("default")

// Define your search index
index := mongo.SearchIndexModel{
Definition: bson.D{
{"mappings", bson.D{
{"dynamic", false},
{"fields", bson.D{
{"released", bson.D{
{"type", "date"},
}},
}},
}},
},
Options: opts,
}

// Create the index
result, err := coll.SearchIndexes().CreateOne(ctx, index)
if err != nil {
log.Fatalf("Failed to create search index: %v", err)
}
log.Printf("New index name: %v", result)
}

```  
To learn how to set up and run the following example code, see [Define the Index for the token Type](/docs/search/index/field-types/token-type#std-label-define-index-token-admin-api).  
You can use the MongoDB Search `date` type to index date values. You can query fields of type `date` using the MongoDB Search [range](/docs/search/query/operators-collectors/range#std-label-range-ref), [near](/docs/search/query/operators-collectors/near#std-label-near-ref), [in](/docs/search/query/operators-collectors/in#std-label-in-ref), and [equals](/docs/search/query/operators-collectors/equals#std-label-equals-ref) operators. You can also run a [facet](/docs/search/query/operators-collectors/facet#std-label-fts-facet-ref) query on `date` type fields.  
You can also use the `date` type to index:  
- Fields whose value is an array of dates. To learn more, see [How to Index the Elements of an Array.](/docs/search/index/field-types/array-type#std-label-fts-array-ref)  
- Date fields inside an array of documents indexed as the [embeddedDocuments](/docs/search/index/field-types/embedded-documents-type#std-label-bson-data-types-embedded-documents) type.  
- Date fields for sorting. MongoDB Search automatically indexes all date fields in indexes created after [July 2023](https://www.mongodb.com/docs/atlas/search-changelog/#std-label-fts20230710) for [sorting](/docs/search/query/sort#std-label-sort-ref) the MongoDB Search results. For preexisting indexes, you must rebuild the index to use date fields in the index for sorting. To learn more, see [Update and Rebuild an Existing MongoDB Search Index](/docs/search/index/manage-indexes#std-label-fts-index-rebuild) and [Sort MongoDB Search Results.](/docs/search/query/sort#std-label-sort-ref)  
**Note:**  
To query indexed date values inside arrays, you must use the [range](/docs/search/query/operators-collectors/range#std-label-range-ref) operator. You can't use the [near](/docs/search/query/operators-collectors/near#std-label-near-ref) operator to query date values stored in an array, even if you have a MongoDB Search index on the date values inside the array.  
If you enable [dynamic mappings](/docs/search/index/define-field-mappings#std-label-static-dynamic-mappings), MongoDB Search automatically indexes fields of type `date`. You can use the **Visual Editor** or the  **JSON Editor** in the Atlas UI to index fields as the `date` type.

