"type": "document",
"dynamic": true|false | {
"typeSeet": "<typeSet-name>"
},
"fields": {
"<sub-field-name>": {
"<field-mapping-definition>" : {}
},
...
}
},
...
}
},
"typeSets": [
{
"name": "<typeSet-name>",
"types": [
{
"type": "<field-type>",
...
},
...
]
},
...
]
}

```  
