"typeSet": "<typeSet-name>"
},
"fields": {
"<field-name>": {
<field-mapping-definition>
}
},
"storedSource": true|false | {
"include | exclude": {
"<field-name>",
...
}
}
}
}
},
"typeSets": [
{
"name": "<typeSet-name>",
