To learn how to set up and run the following example code, see [Define the Index for the token Type](/docs/search/index/field-types/token-type#std-label-define-index-token-admin-api).  
The following index definition for the `sample_airbnb.listingsAndReviews` collection indexes the `address.location` field as the `geo` type. This index allows you to query against that field by using the MongoDB Search [geoShape](/docs/search/query/operators-collectors/geoShape#std-label-geoshape-ref) and [geoWithin](/docs/search/query/operators-collectors/geoWithin#std-label-geowithin-ref) operators.  
```javascript
const { MongoClient } = require("mongodb");

// Replace the connection string with your MongoDB deployment's connection string
const uri =  "<connection-string>";

const client = new MongoClient(uri);

async function run() {
try {
const database = client.db("sample_airbnb");
const collection = database.collection("listingsAndReviews");

// Create the MongoDB Search index definition for the geo field
const index = {
name: "default",
definition: {
"mappings": {
"dynamic": false,
"fields": {
"address": {
"type": "document",
"fields": {
"location": {
"type": "geo",
"indexShapes": true
}
}
}
}
}
}
}

// Create the index
const result = await collection.createSearchIndex(index);
console.log("New index name: " + result);
} finally {
await client.close();
}
}

run().catch(console.dir);
```

