"go.mongodb.org/mongo-driver/v2/bson"
"go.mongodb.org/mongo-driver/v2/mongo"
"go.mongodb.org/mongo-driver/v2/mongo/options"
)

func main() {
ctx := context.Background()
uri := "<connection-string>"
client, err := mongo.Connect(options.Client().
ApplyURI(uri))
if err != nil {
panic(err)
}

defer func() {
if err := client.Disconnect(context.TODO()); err != nil {
panic(err)
}
}()

coll := client.Database("sample_mflix").Collection("movies")
const indexName = "default"
opts := options.SearchIndexes().SetName(indexName).SetType("search")

// Define the MongoDB Search index for the token field
searchIndexModel := mongo.SearchIndexModel{
Definition: bson.D{
{"mappings", bson.D{
{"dynamic", false},
{"fields", bson.D{
{"title", bson.D{
{"type", "token"},
}},
}},
}},
},
Options: opts,
}

// Create the index
searchIndexName, err := coll.SearchIndexes().CreateOne(ctx, searchIndexModel)
if err != nil {
log.Fatalf("Failed to create the Atlas Search index: %v", err)
}

fmt.Println("Name of index created: " + searchIndexName)
}
```  
You must use the MongoDB Search `token` type to index [string](https://www.mongodb.com/docs/manual/reference/bson-types/#std-label-document-bson-type-string) fields to enable sorting and faceting on these fields. Then, you can perform the following actions:  
- Use the `sort` option in your query to sort the results by the indexed field. To learn more, see [Sort MongoDB Search Results.](/docs/search/query/sort#std-label-sort-ref)  
- Use the `facet` collector in your query to group the results by the indexed field. To learn more, see [How to Use Facets with MongoDB Search.](/docs/search/tutorial/facet-tutorial#std-label-facet-tutorial)  
Additionally, you must index string fields as the `token` type in order to use the [equals](/docs/search/query/operators-collectors/equals#std-label-equals-ref), [in](/docs/search/query/operators-collectors/in#std-label-in-ref) and [range](/docs/search/query/operators-collectors/range#std-label-range-ref) operators. To learn more, see the documentation for each respective [operator.](/docs/search/query/operators-collectors/overview#std-label-operators-ref)  
**Note:**  
You can also use the `token` type to index string fields for pre-filtering your data for [`$vectorSearch`](https://www.mongodb.com/docs/vector-search/query/aggregation-stages/vector-search-stage/#mongodb-pipeline-pipe.-vectorSearch) queries. To learn more, see [MongoDB Vector Search Overview.](https://www.mongodb.com/docs/vector-search/#std-label-fts-vector-search)

