{
"$search": {
"compound":{
"must":[{
"moreLikeThis": {
"like": movie
}
}],
"mustNot":[{
"equals": {
"path": "_id",
"value": ObjectId ("573a1396f29313caabce4a9a")
}
}]
}
}
},
{"$limit": 5},
{
"$project": {
"_id": 1,
"title": 1,
"released": 1,
"genres": 1
}
}
])
```  
