- Specifies the [highlight](/docs/search/query/highlighting#std-label-highlight-ref) option to return snippets of text from the `title` field that match the query. The snippets contain matching text specified with `type: 'hit'`, and adjacent text specified with `type: 'text'`.  
- Uses the following pipeline stages:  
- [`$limit`](https://www.mongodb.com/docs/manual/reference/operator/aggregation/limit/#mongodb-pipeline-pipe.-limit) stage to limit the output to 10 results  
- [`$project`](https://www.mongodb.com/docs/manual/reference/operator/aggregation/project/#mongodb-pipeline-pipe.-project) stage to:  
- Exclude all fields except `title` and `year`  
- Add two fields named `score` and `highlights`  
- Iterates over the cursor to print the documents that match the query.  
```csharp
using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using MongoDB.Bson.Serialization.Conventions;
using MongoDB.Driver;
using MongoDB.Driver.Search;

public class CompoundConstantExample
{
private const string MongoConnectionString = "<connection-string>";

public static void Main(string[] args)
{
// allow automapping of the camelCase database fields to our MovieDocument
var camelCaseConvention = new ConventionPack { new CamelCaseElementNameConvention() };
ConventionRegistry.Register("CamelCase", camelCaseConvention, type => true);

// connect to your Atlas cluster
var mongoClient = new MongoClient(MongoConnectionString);
var mflixDatabase = mongoClient.GetDatabase("sample_mflix");
var moviesCollection = mflixDatabase.GetCollection<MovieDocument>("movies");

// define and run pipeline
var results = moviesCollection.Aggregate()
.Search(Builders<MovieDocument>.Search.Compound()
.Filter(Builders<MovieDocument>.Search.Range(movie => movie.Year, SearchRangeBuilder.Gte(2013).Lte(2015)))
.Should(Builders<MovieDocument>.Search.Text(movie => movie.Title, "snow", score: new SearchScoreDefinitionBuilder<MovieDocument>().Constant(5))),
new SearchHighlightOptions<MovieDocument>(movie => movie.Title),
indexName: "default")
.Project<MovieDocument>(Builders<MovieDocument>.Projection
.Include(movie => movie.Title)
.Include(movie => movie.Year)
.Exclude(movie => movie.Id)
.MetaSearchScore(movie => movie.Score)
.MetaSearchHighlights("highlights"))
.Limit(10)
.ToList();

// print results
foreach (var movie in results)
{
Console.WriteLine(movie.ToJson());
}
}
}

