"score": {
"$meta": "searchScore"
}
}
},
{
"$setWindowFields": {
"output": {
"maxScore": {
"$max": "$score"
}
}
}
},
{
"$addFields": {
"normalizedScore": {
"$divide": [
"$score", "$maxScore"
]
}
}
}])
```  
